main { max-width: 34rem; margin: auto; padding: 1rem; }
h1 { font-size: 2.25rem; margin: 0; letter-spacing: -.04em; }
button { font: inherit; font-weight: 700; color: #0e2520; background: #a8f3bf; border: 0; padding: .55rem .9rem; border-radius: .35rem; cursor: pointer; }
button:focus-visible { outline: 3px solid #ffd17e; outline-offset: 2px; }
#board { display: grid; grid-template-columns: repeat(4, 1fr); gap: .4rem; }
#board button { min-height: 2.75rem; }
#board button:disabled { background: #344343; color: #d5e4d6; cursor: default; }

