const start = document.querySelector('#start-game');
const status = document.querySelector('#game-status');
const board = document.querySelector('#board');
let next, deadline, timer;

function showProgress() {
  const seconds = Math.max(0, Math.ceil((deadline - Date.now()) / 1000));
  if (!seconds) {
    finish(false);
    return false;
  }
  status.textContent = 'Nästa prisma: ' + next + ' · ' + seconds + ' sekunder kvar';
  return true;
}

function finish(won) {
  clearInterval(timer);
  status.dataset.state = won ? 'won' : 'lost';
  status.textContent = won ? 'Alla tolv prismor är dina!' : 'Tiden tog slut.';
  for (const tile of board.children) tile.disabled = true;
  start.focus();
}

start.addEventListener('click', () => {
  clearInterval(timer);
  next = 1;
  deadline = Date.now() + 30000;
  status.dataset.state = 'playing';
  board.replaceChildren();
  const numbers = Array.from({ length: 12 }, (_, index) => index + 1);
  for (let i = numbers.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [numbers[i], numbers[j]] = [numbers[j], numbers[i]];
  }
  for (const number of numbers) {
    const tile = document.createElement('button');
    tile.textContent = number;
    tile.addEventListener('click', () => {
      if (!showProgress() || number !== next) return;
      tile.disabled = true;
      next++;
      if (next > numbers.length) finish(true);
      else {
        showProgress();
        (tile.nextElementSibling?.disabled === false ? tile.nextElementSibling : board.querySelector('button:enabled'))?.focus();
      }
    });
    board.append(tile);
  }
  start.textContent = 'Börja om';
  showProgress();
  board.firstElementChild.focus();
  timer = setInterval(showProgress, 200);
});
